//! CLI inbound port

use std::{path::PathBuf, str::FromStr};

use clap::{Parser, Subcommand};

use crate::{
    domain::{
        models::entity_ingestion::{
            DeclarationIngestionStage, EntityIngestionRequest, IngestionKey, MemberIngestionStage,
        },
        services::declaration_cleaning::DeclarationCleanerService,
        services::declaration_fetch::DeclarationFetcherService,
        services::declaration_loading::DeclarationLoaderService,
        services::declaration_resolution::DeclarationResolverService,
        services::entity_ingestion::{
            EntityFetcherService, EntityIngesterService, FetcherService, IngesterService,
        },
    },
    inbound::cli::config::{
        DataConfig, DeclarationFetcherConfig, DeclarationResolverConfig, FetcherConfig,
        LoaderConfig,
    },
    outbound::{ExposedDataPipeline, ExposedDatabase, ParliamentApiClient, SplinkScorer},
};

pub mod config;

/// CLI Data Args
#[derive(Parser)]
pub struct DataArgs {
    #[command(subcommand)]
    command: DataCommands,
}

/// CLI Subcommands
#[derive(Subcommand)]
#[allow(missing_docs)]
pub enum DataCommands {
    /// Show the latest ingestion key and directory path.
    Latest {
        /// YAML configuration with the ingestion `data_dir`.
        config: PathBuf,
    },
    /// Copy the latest raw capture into a new ingestion run.
    CopyLatestRaw {
        /// YAML configuration with the ingestion `data_dir`.
        config: PathBuf,
        /// Destination ingestion key. Defaults to a fresh UUID-v7.
        #[arg(long)]
        ingestion_key: Option<IngestionKey>,
    },
    Declarations {
        /// Stage to run: fetch, clean, resolve, or load.
        #[arg(value_parser = ["fetch", "clean", "resolve", "load"])]
        stage: String,
        /// YAML configuration containing the declaration `data_dir`.
        config: PathBuf,
        /// Ingestion run to clean, resolve, or load.
        #[arg(long)]
        ingestion_key: Option<IngestionKey>,
    },
    Members {
        stage: String,
        config: PathBuf,
        #[arg(long)]
        ingestion_key: Option<IngestionKey>,
    },
}

/// Entry point for CLI commands
///
/// # Errors
/// - Bad stage arg
/// - Bad config path
/// - Bad config shape
/// - Missing or non-Unicode `DATABASE_URL` for commands that use the database
/// - Service level failures
pub async fn run_cli(args: DataArgs) -> anyhow::Result<()> {
    match args.command {
        DataCommands::Latest { config } => {
            let config = LoaderConfig::try_from(&config)?;
            match ExposedDataPipeline::latest_ingestion(&config.data_dir).await? {
                Some((path, key)) => {
                    println!("Ingestion key: {key}");
                    println!("Path: {}", path.display());
                }
                None => println!("No ingestion runs found."),
            }
        }
        DataCommands::CopyLatestRaw {
            config,
            ingestion_key,
        } => {
            let config = LoaderConfig::try_from(&config)?;
            let key = ingestion_key.unwrap_or_default();
            match ExposedDataPipeline::copy_latest_raw(&config.data_dir, key.clone()).await? {
                Some((path, source_key)) => {
                    println!("Source ingestion key: {source_key}");
                    println!("Ingestion key: {key}");
                    println!("Path: {}", path.display());
                }
                None => println!("No ingestion runs found."),
            }
        }
        DataCommands::Declarations {
            stage,
            config,
            ingestion_key,
        } => match DeclarationIngestionStage::from_str(&stage)? {
            DeclarationIngestionStage::Fetch => {
                let config = DeclarationFetcherConfig::try_from(&config)?;
                let data_config = DataConfig::from_env()?;
                let api = ParliamentApiClient::new(config.batch_size)?;
                let db = ExposedDatabase::new(&data_config.connection_string).await;
                let fs = ExposedDataPipeline::new_with_ingestion_key(
                    &config.data_dir,
                    ingestion_key.unwrap_or_default(),
                )?;
                DeclarationFetcherService::new(db, api, fs)
                    .fetch_declarations()
                    .await?;
            }
            DeclarationIngestionStage::Resolve => {
                let ingestion_key = ingestion_key.ok_or_else(|| {
                    anyhow::anyhow!("declarations resolve requires --ingestion-key")
                })?;
                let config = DeclarationResolverConfig::try_from(&config)?;
                let storage = ExposedDataPipeline::open_cleaned_declarations(
                    &config.data_dir,
                    ingestion_key.clone(),
                )?;
                let scorer = SplinkScorer::new(config.resolution_python, config.resolution_worker)?;
                let summary =
                    DeclarationResolverService::new(storage, scorer, config.candidate_budget)
                        .resolve_declarations()
                        .await?;
                println!("Ingestion key: {ingestion_key}");
                println!(
                    "Resolved declarations: {}",
                    std::path::absolute(config.data_dir)?
                        .join(ingestion_key.to_string())
                        .join("resolved/declarations")
                        .display()
                );
                println!("Observations: {}", summary.observations);
                println!("Funding occurrences: {}", summary.payments);
                println!("Pair decisions: {}", summary.pairs);
            }
            DeclarationIngestionStage::Load => {
                let ingestion_key = ingestion_key
                    .ok_or_else(|| anyhow::anyhow!("declarations load requires --ingestion-key"))?;
                let config = LoaderConfig::try_from(&config)?;
                let data_config = DataConfig::from_env()?;
                let storage = ExposedDataPipeline::open_resolved_declarations(
                    &config.data_dir,
                    ingestion_key.clone(),
                )?;
                let db = ExposedDatabase::new(&data_config.connection_string).await;
                let summary = DeclarationLoaderService::new(storage, db)
                    .load_declarations()
                    .await?;
                println!("Ingestion key: {ingestion_key}");
                match summary.outcome {
                    crate::domain::models::declaration_loading::DeclarationLoadOutcome::Imported => {
                        println!("Loaded declarations: {}", summary.declarations);
                    }
                    crate::domain::models::declaration_loading::DeclarationLoadOutcome::AlreadyLoaded => {
                        println!("Run already loaded. Declarations: {}", summary.declarations);
                    }
                }
                println!("Resolved identities: {}", summary.funders);
                println!("Funding occurrences: {}", summary.funding_entries);
            }
            DeclarationIngestionStage::Clean => {
                let ingestion_key = ingestion_key.ok_or_else(|| {
                    anyhow::anyhow!("declarations clean requires --ingestion-key")
                })?;
                let config = LoaderConfig::try_from(&config)?;
                let fs = ExposedDataPipeline::open_existing_declarations(
                    &config.data_dir,
                    ingestion_key.clone(),
                )?;
                let summary = DeclarationCleanerService::new(fs)
                    .clean_declarations()
                    .await?;
                println!("Ingestion key: {ingestion_key}");
                println!(
                    "Cleaned declarations: {}",
                    std::path::absolute(&config.data_dir)?
                        .join(ingestion_key.to_string())
                        .join("cleaned/declarations")
                        .display()
                );
                println!("Member partitions: {}", summary.member_partitions);
                println!("Declarations: {}", summary.declarations);
                println!("Funding entries: {}", summary.funding_entries);
                println!("Funder observations: {}", summary.funders);
            }
        },
        DataCommands::Members {
            stage,
            config,
            ingestion_key,
        } => {
            let stage = MemberIngestionStage::from_str(&stage)?;
            let ingestion_key = ingestion_key.unwrap_or_default();
            match stage {
                MemberIngestionStage::Fetch => {
                    let config = FetcherConfig::try_from(&config)?;
                    let api = ParliamentApiClient::new(config.batch_size)?;
                    let fs = ExposedDataPipeline::new_with_ingestion_key(
                        &config.data_dir,
                        ingestion_key,
                    )?;
                    let service = FetcherService::new(fs, api);

                    let req = EntityIngestionRequest {};
                    service.fetch_members(&req).await?;
                }
                MemberIngestionStage::Load => {
                    let config = LoaderConfig::try_from(&config)?;
                    let data_config = DataConfig::from_env()?;
                    let fs = ExposedDataPipeline::new_with_ingestion_key(
                        &config.data_dir,
                        ingestion_key,
                    )?;
                    let db = ExposedDatabase::new(&data_config.connection_string).await;
                    let service = IngesterService::new(fs, db);

                    service.load_members().await?;
                }
            }
        }
    }
    Ok(())
}
use clap::{Parser, Subcommand};
use exposed::inbound::{
    cli::{DataArgs, run_cli},
    http::server::run_server,
};

#[derive(Parser)]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand)]
enum Commands {
    Server,
    Data(DataArgs),
}

fn main() -> anyhow::Result<()> {
    let args = Cli::parse();
    match args.command {
        Commands::Server => run_server(),
        Commands::Data(args) => {
            dotenvy::dotenv().ok();
            tokio::runtime::Runtime::new()?.block_on(run_cli(args))
        }
    }
}
use arrow::json::ArrayWriter;
use chrono::{NaiveDate, Utc};
use exposed::{
    domain::{
        models::{
            declaration_ingestion::{
                CapturedDeclaration, CapturedFundingEntry, DeclarationId, MemberAsId,
            },
            entity_ingestion::IngestionKey,
        },
        repositories::entity_ingestion::EntityIngestionStorage,
    },
    outbound::ExposedDataPipeline,
};
use parquet::arrow::arrow_reader::ParquetRecordBatchReaderBuilder;
use serde_json::{Value, json};
use std::{
    collections::{BTreeMap, BTreeSet},
    fs,
    path::Path,
    process::Command,
};
use uuid::Uuid;

fn rows(path: &Path) -> anyhow::Result<Vec<Value>> {
    let reader = ParquetRecordBatchReaderBuilder::try_new(fs::File::open(path)?)?.build()?;
    let mut rows = Vec::new();
    for batch in reader {
        let mut writer = ArrayWriter::new(Vec::new());
        writer.write(&batch?)?;
        writer.finish()?;
        rows.extend(serde_json::from_slice::<Vec<Value>>(&writer.into_inner())?);
    }
    Ok(rows)
}
fn run(stage: &str, config: &Path, key: &IngestionKey) -> std::process::Output {
    Command::new(env!("CARGO_BIN_EXE_exposed"))
        .args(["data", "declarations", stage])
        .arg(config)
        .arg("--ingestion-key")
        .arg(key.to_string())
        .env_remove("DATABASE_URL")
        .output()
        .unwrap()
}
#[tokio::test]
#[ignore = "requires built CLI, SQLx compile-time database, and EXPOSED_RESOLUTION_PYTHON with pinned Splink"]
async fn clean_then_resolve_with_real_splink_preserves_occurrences_and_refuses_overwrite()
-> anyhow::Result<()> {
    let python = std::env::var("EXPOSED_RESOLUTION_PYTHON")?;
    let temporary = tempfile::tempdir()?;
    let key = IngestionKey::default();
    let root = temporary.path().join("data");
    let storage = ExposedDataPipeline::new_with_ingestion_key(&root, key.clone())?;
    let member = MemberAsId::new(Uuid::from_u128(1), 1)?;
    let date = NaiveDate::from_ymd_opt(2026, 9, 7).unwrap();
    let mut captures = Vec::new();
    for id in 1..=16 {
        let (name, kind) = match id {
            1 | 2 => ("Example Charity", "Charity"),
            3..=6 => ("Gary Lubner", "Individual"),
            7 => ("HSBC UK Bank PLC", "Company"),
            8 => ("HSBC UK (Ian Stuart, CEO)", "Company"),
            9 => ("Unite Union", "Trade Union"),
            10 => ("UNITE the Union West Midlands", "Trade Union"),
            11 => ("East Midlands Unite the Union", "Trade Union"),
            12 => ("Unite the Union Parliamentary Staff Branch", "Trade Union"),
            13 => ("Northstar Consulting trading as Fletchers", "Company"),
            14 => ("Fletchers", "Company"),
            15 => ("Carlton Club", "Unincorporated association"),
            16 => (
                "Carlton Club Political Committee",
                "Unincorporated association",
            ),
            _ => unreachable!(),
        };
        let address = match id {
            1 | 2 => Some("10 Example Road, London SW1A 1AA"),
            5 => Some("20 Other Road, London SW1A 1AA"),
            6 => Some("30 Other Road, London SW1A 1AA"),
            7 => Some("1 Centenary Square, Birmingham, B1 1HQ"),
            8 => Some("1 Centenary Square Birmingham B1 1HQ"),
            15 | 16 => Some("69 St James Street, London SW1A 1PJ"),
            _ => None,
        };
        let mut fields = vec![
            json!({"name":"DonorName","value":name}),
            json!({"name":"DonorStatus","value":kind}),
            json!({"name":"Value","value":"100"}),
        ];
        if let Some(address) = address {
            fields.push(json!({"name":"DonorPublicAddress","value":address}));
        }
        let source = json!({"id":id,"category":{"id":3,"name":"Donations"},"versions":[{"register":{"id":820,"publishedDate":"2026-09-07"},"fields":fields}]});
        captures.push(CapturedDeclaration::new(
            DeclarationId::new(id)?,
            None,
            3,
            "Donations".into(),
            820,
            date,
            None,
            vec![CapturedFundingEntry::new(
                None,
                Some(name.into()),
                None,
                Some("100".into()),
                None,
                None,
                Some(kind.into()),
                None,
                None,
            )],
            Utc::now(),
            source.to_string(),
        )?);
    }
    storage.write_raw_declarations(member, &captures).await?;
    let config = temporary.path().join("resolution.yaml");
    let worker = Path::new(env!("CARGO_MANIFEST_DIR")).join("../resolution/worker.py");
    fs::write(
        &config,
        format!(
            "data_dir: {}\nresolution_python: {}\nresolution_worker: {}\ncandidate_budget: 100\n",
            serde_json::to_string(&root)?,
            serde_json::to_string(&python)?,
            serde_json::to_string(&worker)?
        ),
    )?;
    let source_key = key;
    let key = IngestionKey::default();
    let copied = Command::new(env!("CARGO_BIN_EXE_exposed"))
        .args(["data", "copy-latest-raw"])
        .arg(&config)
        .arg("--ingestion-key")
        .arg(key.to_string())
        .env_remove("DATABASE_URL")
        .output()?;
    assert!(
        copied.status.success(),
        "{}",
        String::from_utf8_lossy(&copied.stderr)
    );
    assert!(
        root.join(source_key.to_string())
            .join("raw/declarations")
            .is_dir()
    );
    let clean = run("clean", &config, &key);
    assert!(
        clean.status.success(),
        "{}",
        String::from_utf8_lossy(&clean.stderr)
    );
    let cleaned = root.join(key.to_string()).join("cleaned/declarations");
    let before = fs::read(cleaned.join("funders.parquet"))?;
    let payments_before = fs::read(cleaned.join("funding_entries.parquet"))?;
    let funders = rows(&cleaned.join("funders.parquet"))?;
    let names = funders
        .iter()
        .map(|row| {
            (
                row["funder_id"].as_str().unwrap(),
                row["name_raw"].as_str().unwrap(),
            )
        })
        .collect::<BTreeMap<_, _>>();
    fs::remove_dir_all(root.join(key.to_string()).join("raw"))?;
    let resolved = run("resolve", &config, &key);
    assert!(
        resolved.status.success(),
        "{}",
        String::from_utf8_lossy(&resolved.stderr)
    );
    let output = root.join(key.to_string()).join("resolved/declarations");
    let observations = rows(&output.join("observation_resolution.parquet"))?;
    assert_eq!(observations.len(), 16);
    assert_eq!(
        observations
            .iter()
            .map(|r| r["identity_id"].as_str().unwrap())
            .collect::<BTreeSet<_>>()
            .len(),
        7
    );
    for (name, basis, count) in [
        ("Example Charity", "statistical_link", 2),
        ("Gary Lubner", "donor_name_link", 4),
    ] {
        let members = observations
            .iter()
            .filter(|row| names[row["funder_id"].as_str().unwrap()] == name)
            .collect::<Vec<_>>();
        assert_eq!(members.len(), count, "membership count for {name}");
        assert!(members.iter().all(|row| row["identity_basis"] == basis));
        assert_eq!(
            members
                .iter()
                .map(|row| row["identity_id"].as_str().unwrap())
                .collect::<BTreeSet<_>>()
                .len(),
            1,
            "one identity for {name}"
        );
    }
    for (prefix, basis, count) in [
        ("HSBC", "extracted_name_link", 2),
        ("Unite", "trade_union_family_link", 4),
    ] {
        let members = observations
            .iter()
            .filter(|row| {
                names[row["funder_id"].as_str().unwrap()]
                    .to_ascii_lowercase()
                    .contains(&prefix.to_ascii_lowercase())
            })
            .collect::<Vec<_>>();
        assert_eq!(members.len(), count, "membership count for {prefix}");
        assert!(members.iter().all(|row| row["identity_basis"] == basis));
        assert_eq!(
            members
                .iter()
                .map(|row| row["identity_id"].as_str().unwrap())
                .collect::<BTreeSet<_>>()
                .len(),
            1,
            "one identity for {prefix}"
        );
    }
    let alias_members = observations
        .iter()
        .filter(|row| {
            let name = names[row["funder_id"].as_str().unwrap()];
            name.contains("Northstar") || name == "Fletchers"
        })
        .collect::<Vec<_>>();
    assert_eq!(alias_members.len(), 2);
    assert!(
        alias_members
            .iter()
            .all(|row| row["identity_basis"] == "extracted_name_link")
    );
    assert_eq!(
        alias_members
            .iter()
            .map(|row| row["identity_id"].as_str().unwrap())
            .collect::<BTreeSet<_>>()
            .len(),
        1
    );
    let distinct_organizations = observations
        .iter()
        .filter(|row| names[row["funder_id"].as_str().unwrap()].starts_with("Carlton Club"))
        .collect::<Vec<_>>();
    assert_eq!(distinct_organizations.len(), 2);
    assert!(
        distinct_organizations
            .iter()
            .all(|row| row["identity_basis"] == "provisional_singleton")
    );
    assert_eq!(
        distinct_organizations
            .iter()
            .map(|row| row["identity_id"].as_str().unwrap())
            .collect::<BTreeSet<_>>()
            .len(),
        2,
        "sharing an address and organization-name root must not merge distinct organizations"
    );
    let attribution = rows(&output.join("payment_attribution.parquet"))?;
    assert_eq!(attribution.len(), 16);
    assert!(
        attribution
            .iter()
            .all(|row| row["attribution_basis"] == "donor")
    );
    let pairs = rows(&output.join("pair_decisions.parquet"))?;
    assert_eq!(pairs.len(), 16);
    let negative_pair = pairs
        .iter()
        .find(|pair| {
            names[pair["left_funder_id"].as_str().unwrap()].starts_with("Carlton Club")
                && names[pair["right_funder_id"].as_str().unwrap()].starts_with("Carlton Club")
        })
        .expect("the real worker must score the shared-address organization pair");
    assert_eq!(negative_pair["disposition"], "review");
    assert_eq!(negative_pair["reason"], "insufficient_exact_evidence");
    for pair in &pairs {
        let left_name = names[pair["left_funder_id"].as_str().unwrap()];
        let right_name = names[pair["right_funder_id"].as_str().unwrap()];
        if left_name.starts_with("Carlton Club") {
            assert_ne!(left_name, right_name);
            assert_eq!(pair["disposition"], "review");
            continue;
        }
        assert_eq!(pair["disposition"], "accepted");
        if left_name == "Gary Lubner" {
            assert_eq!(left_name, right_name);
            assert_eq!(pair["reason"], "exact_donor_name");
            assert!(pair["probability"].as_f64().unwrap() < 0.999);
            assert!(pair["probability"].as_f64().unwrap() > 0.0);
        } else if left_name.contains("HSBC") || right_name.contains("HSBC") {
            assert_eq!(pair["reason"], "extracted_name_evidence");
        } else if left_name.contains("Unite") || right_name.contains("Unite") {
            assert_eq!(pair["reason"], "trade_union_family");
        } else if left_name.contains("Northstar") || right_name.contains("Northstar") {
            assert_eq!(pair["reason"], "extracted_name_evidence");
        } else {
            assert_eq!(left_name, right_name);
            assert_eq!(pair["reason"], "exact_name_full_address_threshold");
        }
    }
    let manifest = fs::read(output.join("manifest.json"))?;
    let model: Value = serde_json::from_slice(&manifest)?;
    assert_eq!(model["model"]["splink_version"], "4.0.17");
    assert_eq!(model["model"]["calibrated"], false);
    assert_eq!(model["policy_version"], "funder-resolution-v3");
    assert_eq!(fs::read(cleaned.join("funders.parquet"))?, before);
    assert_eq!(
        fs::read(cleaned.join("funding_entries.parquet"))?,
        payments_before
    );
    assert!(!run("resolve", &config, &key).status.success());
    assert_eq!(fs::read(output.join("manifest.json"))?, manifest);
    Ok(())
}
